    /// <summary>
    /// Returns the list of revenue transactions for a chat. Currently, this method can be used only
    /// for channels if supergroupFullInfo.can_get_revenue_statistics == true or bots if userFullInfo.bot_info.can_get_revenue_statistics == true
    /// </summary>
    public Task<TdLib.TdApi.Objects.ChatRevenueTransactions> GetChatRevenueTransactionsAsync(long chatId = default, string offset = default, int limit = default)
    {

           using var activity =  StartCallActivity("GetChatRevenueTransactionsAsync", typeof(GetChatRevenueTransactions).FullName ?? "GetChatRevenueTransactionsAsync");

           try
           {
             return client.GetChatRevenueTransactionsAsync(chatId, offset, limit);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
